import AppKit
import ImageIO

// Dispatch inline on the main thread; never synchronously redispatch to itself.
// Callers must not hold a mutex that a main-thread command may acquire.
private func whisperaClipboardOnMain<T>(_ body: () -> T) -> T {
    if Thread.isMainThread { return body() }
    return DispatchQueue.main.sync(execute: body)
}

private let whisperaClipboardLimit = 160_000_000
private let whisperaClipboardExcluded: Set<String> = [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
    "Pasteboard generator type"
]
private let whisperaLegacyFiles = NSPasteboard.PasteboardType("NSFilenamesPboardType")

private func whisperaClipboardIsExcluded(_ board: NSPasteboard) -> Bool {
    let types = (board.types ?? []) + (board.pasteboardItems ?? []).flatMap { $0.types }
    return types.contains { whisperaClipboardExcluded.contains($0.rawValue) }
}

private func whisperaClipboardFiles(_ board: NSPasteboard) -> [String]? {
    guard board.availableType(from: [.fileURL, whisperaLegacyFiles]) != nil else { return nil }
    if let urls = board.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL], !urls.isEmpty {
        return urls.filter { $0.isFileURL }.map { $0.path }
    }
    return board.propertyList(forType: whisperaLegacyFiles) as? [String] ?? []
}

private struct WhisperaClipboardSnapshot {
    var sequence: Int64
    var kind: Int32 = 0
    var data: Data = Data()
}

@_cdecl("whispera_clipboard_sequence")
public func whisperaClipboardSequence() -> Int64 {
    whisperaClipboardOnMain { Int64(NSPasteboard.general.changeCount) }
}

private func whisperaClipboardSnapshot(_ previous: Int64) -> WhisperaClipboardSnapshot {
    let board = NSPasteboard.general
    let count = board.changeCount
    var snapshot = WhisperaClipboardSnapshot(sequence: Int64(count))
    if snapshot.sequence == previous || whisperaClipboardIsExcluded(board) { return snapshot }
    if let files = whisperaClipboardFiles(board) {
        if let encoded = try? JSONSerialization.data(withJSONObject: files) {
            snapshot.kind = 1
            snapshot.data = encoded
        } else { snapshot.kind = -1 }
    } else if let data = board.data(forType: .png) ?? board.data(forType: .tiff) {
        snapshot.kind = 2
        snapshot.data = data
    } else if let text = board.string(forType: .string) ?? board.string(forType: .URL), text.utf8.count <= 262_144 {
        snapshot.kind = 3
        snapshot.data = Data(text.utf8)
    }
    // Another app can take ownership while a lazy pasteboard provider is reading.
    if board.changeCount != count || whisperaClipboardIsExcluded(board) {
        snapshot.kind = -1
        snapshot.data = Data()
    }
    return snapshot
}

private func whisperaClipboardPNG(_ data: Data) -> Data? {
    guard data.count <= whisperaClipboardLimit,
          let source = CGImageSourceCreateWithData(data as CFData, nil),
          let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [String: Any],
          let width = properties[kCGImagePropertyPixelWidth as String] as? NSNumber,
          let height = properties[kCGImagePropertyPixelHeight as String] as? NSNumber else { return nil }
    let w = width.doubleValue, h = height.doubleValue
    guard w > 0, h > 0, w * h <= 40_000_000 else { return nil }
    if CGImageSourceGetType(source) as String? == "public.png" { return data }
    guard let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return nil }
    let output = NSMutableData()
    guard let destination = CGImageDestinationCreateWithData(output, "public.png" as CFString, 1, nil) else { return nil }
    CGImageDestinationAddImage(destination, image, nil)
    guard CGImageDestinationFinalize(destination), output.length <= whisperaClipboardLimit else { return nil }
    return output as Data
}

// Kinds: 0 unchanged/empty/excluded, 1 JSON file paths, 2 PNG, 3 UTF-8, -1 error.
// Rust owns the returned allocation and must release it with the matching free.
@_cdecl("whispera_clipboard_read")
public func whisperaClipboardRead(_ previous: Int64, _ sequence: UnsafeMutablePointer<Int64>, _ kind: UnsafeMutablePointer<Int32>, _ length: UnsafeMutablePointer<Int>) -> UnsafeMutablePointer<UInt8>? {
    autoreleasepool {
        var snapshot = whisperaClipboardOnMain { whisperaClipboardSnapshot(previous) }
        // Image decoding/encoding stays off the UI thread when called by history.
        if snapshot.kind == 2 {
            if let png = whisperaClipboardPNG(snapshot.data) { snapshot.data = png }
            else { snapshot.kind = -1; snapshot.data = Data() }
        }
        if snapshot.data.count > whisperaClipboardLimit { snapshot.kind = -1; snapshot.data = Data() }
        sequence.pointee = snapshot.sequence
        kind.pointee = snapshot.kind
        length.pointee = snapshot.data.count
        guard !snapshot.data.isEmpty else { return nil }
        let output = UnsafeMutablePointer<UInt8>.allocate(capacity: snapshot.data.count)
        snapshot.data.copyBytes(to: output, count: snapshot.data.count)
        return output
    }
}

@_cdecl("whispera_clipboard_free")
public func whisperaClipboardFree(_ data: UnsafeMutablePointer<UInt8>?) {
    data?.deallocate()
}

@_cdecl("whispera_clipboard_write_files")
public func whisperaClipboardWriteFiles(_ bytes: UnsafePointer<UInt8>, _ length: Int, _ expectedBytes: UnsafePointer<UInt8>?, _ expectedLength: Int, _ sequence: UnsafeMutablePointer<Int64>) -> Int32 {
    autoreleasepool {
        sequence.pointee = -1
        guard length > 0, length <= 4_194_304,
              let files = (try? JSONSerialization.jsonObject(with: Data(bytes: bytes, count: length))) as? [String], !files.isEmpty else { return -1 }
        var expected: [[String]]? = nil
        if let expectedBytes = expectedBytes {
            guard expectedLength > 0, expectedLength <= 4_194_304,
                  let alternatives = (try? JSONSerialization.jsonObject(with: Data(bytes: expectedBytes, count: expectedLength))) as? [[String]], !alternatives.isEmpty else { return -1 }
            expected = alternatives
        }
        // Validate everything before clearContents, including an absent sidecar.
        for path in files {
            var directory: ObjCBool = false
            guard (path as NSString).isAbsolutePath, !path.utf8.contains(0),
                  FileManager.default.fileExists(atPath: path, isDirectory: &directory), !directory.boolValue else { return -1 }
        }
        let urls = files.map { NSURL(fileURLWithPath: $0, isDirectory: false) }
        return whisperaClipboardOnMain {
            let board = NSPasteboard.general
            if let expected = expected {
                let before = board.changeCount
                guard !whisperaClipboardIsExcluded(board),
                      let current = whisperaClipboardFiles(board), expected.contains(current),
                      board.changeCount == before else { return 0 }
            }
            let count = board.clearContents()
            // NSURL writers advertise file URLs, not transcript text or stale PNG.
            guard board.writeObjects(urls) else { return -1 }
            sequence.pointee = Int64(count)
            return 1
        }
    }
}
